
import os
import requests
import pandas as pd
import streamlit as st

# -----------------------------------
# CONFIGURATION
# -----------------------------------

API_URL = os.getenv(
    "API_BASE_URL",
    "http://api:8000"
).rstrip("/")

st.set_page_config(
    page_title="Prediction History",
    page_icon="🤖",
    layout="wide"
)

# -----------------------------------
# HEADER
# -----------------------------------

st.title("🤖 ML Prediction History")

st.caption(
    "Explore historical task predictions generated by the SVM model."
)

# -----------------------------------
# API FUNCTIONS
# -----------------------------------

@st.cache_data(ttl=30)
def fetch_prediction_runs():
    response = requests.get(
        f"{API_URL}/ml/prediction-runs",
        params={"limit": 100},
        timeout=30
    )

    response.raise_for_status()

    return response.json()


def fetch_prediction_history(run_id, page, page_size):
    response = requests.get(
        f"{API_URL}/ml/prediction-runs/{run_id}/history",
        params={
            "page": page,
            "page_size": page_size
        },
        timeout=30
    )

    response.raise_for_status()

    return response.json()


# -----------------------------------
# LOAD PREDICTION RUNS
# -----------------------------------

try:

    with st.spinner("Loading prediction runs..."):
        runs_data = fetch_prediction_runs()

    runs = runs_data.get("runs", [])

    if not runs:

        st.info("No prediction runs are available yet.")
        st.stop()

    # -----------------------------------
    # RUN SUMMARY
    # -----------------------------------

    total_runs = runs_data.get("total_runs", len(runs))

    successful_runs = sum(
        1 for run in runs
        if run.get("RUN_STATUS") == "SUCCESS"
    )

    total_predictions = sum(
        int(run.get("TOTAL_PREDICTIONS", 0))
        for run in runs
    )

    col1, col2, col3 = st.columns(3)

    col1.metric(
        "Total Prediction Runs",
        total_runs
    )

    col2.metric(
        "Successful Runs",
        successful_runs
    )

    col3.metric(
        "Predictions in Loaded Runs",
        total_predictions
    )

    st.divider()

    # -----------------------------------
    # RUN SELECTION
    # -----------------------------------

    st.subheader("Select Prediction Run")

    run_lookup = {
        run["RUN_ID"]: run
        for run in runs
    }

    run_ids = list(run_lookup.keys())

    selected_run_id = st.selectbox(
        "Choose a prediction run",
        options=run_ids,
        format_func=lambda run_id: (
            f"{run_id[:8]}... | "
            f"{run_lookup[run_id].get('RUN_STATUS', 'UNKNOWN')} | "
            f"{run_lookup[run_id].get('TOTAL_PREDICTIONS', 0)} predictions"
        )
    )

    selected_run = run_lookup[selected_run_id]

    # -----------------------------------
    # SELECTED RUN DETAILS
    # -----------------------------------

    st.subheader("Run Details")

    col1, col2, col3 = st.columns(3)

    col1.metric(
        "Run Status",
        selected_run.get("RUN_STATUS", "Unknown")
    )

    col2.metric(
        "Total Predictions",
        selected_run.get("TOTAL_PREDICTIONS", 0)
    )

    col3.metric(
        "Run ID",
        selected_run_id[:8] + "..."
    )

    st.write(
        "**Started At:**",
        selected_run.get("STARTED_AT", "N/A")
    )

    st.write(
        "**Completed At:**",
        selected_run.get("COMPLETED_AT", "N/A")
    )

    st.divider()

    # -----------------------------------
    # PAGINATION SETTINGS
    # -----------------------------------

    st.subheader("Prediction Records")

    page_size = st.selectbox(
        "Records per page",
        options=[5, 10, 25, 50, 100],
        index=2
    )

    # -----------------------------------
    # PAGE STATE
    # -----------------------------------

    page_key = f"history_page_{selected_run_id}"

    if page_key not in st.session_state:
        st.session_state[page_key] = 1

    # -----------------------------------
    # FETCH FIRST PAGE TO GET TOTAL PAGES
    # -----------------------------------

    history_data = fetch_prediction_history(
        selected_run_id,
        page=st.session_state[page_key],
        page_size=page_size
    )

    total_pages = history_data.get("total_pages", 1)

    # Correct page if page size changes.
    current_page = min(
        st.session_state[page_key],
        max(total_pages, 1)
    )

    st.session_state[page_key] = current_page

    if history_data.get("page") != current_page:

        history_data = fetch_prediction_history(
            selected_run_id,
            page=current_page,
            page_size=page_size
        )

    predictions = history_data.get("predictions", [])

    total_records = history_data.get("total_records", 0)

    # -----------------------------------
    # PREDICTION TABLE
    # -----------------------------------

    if predictions:

        df = pd.DataFrame(predictions)

        df = df.rename(columns={
            "TASK_ID": "Task ID",
            "TASK_TITLE": "Task Title",
            "PREDICTION": "Prediction",
            "PREDICTED_STATUS": "Predicted Status",
            "PREDICTED_AT": "Predicted At"
        })

        display_columns = [
            "Task ID",
            "Task Title",
            "Prediction",
            "Predicted Status",
            "Predicted At"
        ]

        df = df[display_columns]

        st.dataframe(
            df,
            use_container_width=True,
            hide_index=True
        )

        # CSV DOWNLOAD

        csv_data = df.to_csv(index=False).encode("utf-8")

        st.download_button(
            label="Download Current Page as CSV",
            data=csv_data,
            file_name=f"prediction_history_page_{current_page}.csv",
            mime="text/csv"
        )

    else:

        st.info("No prediction records found for this page.")

    # -----------------------------------
    # PAGINATION CONTROLS
    # -----------------------------------

    st.divider()

    st.write(
        f"Showing page {current_page} of {total_pages} "
        f"| Total records: {total_records}"
    )

    prev_col, page_col, next_col = st.columns([1, 2, 1])

    with prev_col:

        if st.button(
            "⬅ Previous",
            disabled=current_page <= 1,
            use_container_width=True
        ):

            st.session_state[page_key] = current_page - 1
            st.rerun()

    with page_col:

        st.caption(
            f"Page {current_page} / {total_pages}"
        )

    with next_col:

        if st.button(
            "Next ➡",
            disabled=current_page >= total_pages,
            use_container_width=True
        ):

            st.session_state[page_key] = current_page + 1
            st.rerun()


except requests.exceptions.ConnectionError:

    st.error(
        "Cannot connect to FastAPI. "
        "Please check whether the API container is running."
    )

except requests.exceptions.Timeout:

    st.error("The API request timed out. Please try again.")

except requests.exceptions.HTTPError as error:

    st.error(f"API returned an HTTP error: {error}")

except requests.exceptions.RequestException as error:

    st.error(f"Could not retrieve prediction history: {error}")

except (KeyError, ValueError, TypeError) as error:

    st.error(f"Unexpected prediction history response: {error}")
